"""Rebuilds the Methods Lab artifact page: the original five tools plus the model and full-study tools."""
import sys
from pathlib import Path
T = Path(__file__).parent; sys.path.insert(0, str(T))
from study_tools import TOOLS, rng
BASE = Path("amar-methods-lab.base.html").read_text()
JS = T.parent / "docs" / "js"
def tool(id, n, tag, title, text, body, note=""):
    return f'<section class="tool" id="{id}"><span class="n">Tool {n} · {tag}</span>\n  <h2>{title}</h2>\n  <p>{text}</p>\n{body}\n{f"<p class=note>{note}</p>" if note else ""}</section>\n'
CHK = 'style="display:flex;gap:8px;align-items:center;font-weight:500"'
NEW = '<h2 id="models" style="margin-top:14px">The model behind most severity studies</h2>\n<p class="lede">Property damage only, injury or fatal: how a multinomial logit turns what is known about a crash into three probabilities, and where its numbers come from.</p>\n'
NEW += tool("mnl", 6, "Multinomial logit", "From a crash to three probabilities", "Each outcome has a row of coefficients. Add up the ones that apply to this crash to get a score, turn each score into a weight (e to the power of the score), and take each weight’s share of the total. “No injury” is the base outcome, with a score of 0.",
  f'<div style="display:flex;gap:14px;flex-wrap:wrap"><label {CHK}><input type="checkbox" id="b-belt" checked> No seat belt</label><label {CHK}><input type="checkbox" id="b-speed" checked> High speed limit</label><label {CHK}><input type="checkbox" id="b-night"> Night</label></div>\n<p class="read" id="b-sum" aria-live="polite"></p>\n<svg class="chart" id="b-svg" viewBox="0 0 820 270" role="img" aria-label="Weights and probabilities of three outcomes"></svg>\n<p class="read" id="b-read" aria-live="polite"></p>',
  "Invented coefficients. Injury: constant −0.6, no seat belt +0.9, high speed limit +0.5, night +0.3. Fatal: −2.5, +1.6, +1.1, +0.6.")
NEW += tool("likelihood", 7, "Maximum likelihood", "Where do the coefficients come from?", "The computer tries values and keeps the one that makes the observed data most probable. Ten crashes without a seat belt, seven with an injury: move β and watch the log-likelihood.",
  f'<div class="ctl">{rng("l-b", "Try a value of β", -2, 3, 0.05, 0, "l-bv")}</div>\n<button class="go" id="l-go">Let the computer find the best value</button>\n<svg class="chart" id="l-svg" viewBox="0 0 820 295" role="img" aria-label="Ten crashes and the log-likelihood curve"></svg>\n<p class="read" id="l-read" aria-live="polite"></p>')
NEW += '<h2 id="study" style="margin-top:14px">A full severity study, step by step</h2>\n<p class="lede">The recipe behind many recent papers: split crashes by road class and year, fit a random-parameters logit to each part, then test whether the parts can share a model. Example: truck crashes, three road classes, three years. All numbers are invented.</p>\n'
NEW += tool("chisquare", 8, "Chi-square test", "Does the severity mix differ between two groups?", "Before modelling, compare the counts you observed with the counts you would expect if road class made no difference. Edit the six counts.", TOOLS["chi"])
NEW += tool("selection", 9, "Backward selection", "Which variables stay in the model?", "The t-statistic is the estimate divided by its standard error. A common rule keeps a variable when |t| is at least 1.645. Remove the weakest variable, estimate again, repeat.", TOOLS["sel"].replace('class="go ghost"', 'class="go" style="background:transparent;color:var(--accent)"'))
NEW += tool("random", 10, "Random parameters with heterogeneity in means and variances", "An effect whose mean and spread can move", "The coefficient for crash n is β + Θ × Z + σ × e<sup>ω × W</sup> × a standard normal draw. β is the mean and σ the spread. Θ slides the mean for crashes where indicator Z is 1; ω stretches or shrinks the spread for crashes where W is 1.", TOOLS["rp"], "A parameter is kept as random only if σ is significant and a likelihood ratio test favours the random-parameter model (tool 12, “Random vs fixed”).")
NEW += tool("marginal", 11, "Average marginal effect", "By how many points does the probability change?", "Switch an indicator from 0 to 1 for each crash, holding the rest of the crash as it was, and record the change in probability. The average of those changes is the average marginal effect.", TOOLS["ame"], "Invented coefficients. Injury: constant −0.7, rollover +0.8, 140 km/h +0.3, adverse weather +0.4. Fatal: −2.6, +1.4, +0.9, +0.5.")
NEW += tool("lrtest", 12, "Likelihood ratio tests", "One calculator, four tests", "Transferability: do one road class’s (or year’s) parameters describe another’s crashes? Merge: can two classes share one model? Constrained vs unconstrained: can some parameters be held equal across years? Random vs fixed: do the random parameters earn their place? Type the log-likelihoods (LL) from your own models.", TOOLS["lr"])
NEW += tool("count", 13, "How many tests?", "Counting the comparisons in a study design", "Every pair of road classes is tested in both directions in every year, and every pair of years in both directions for every road class.", TOOLS["cnt"])
import json
REFS = json.load(open(T.parent / "research" / "references.json"))
NEW += '<h2 id="basics" style="margin-top:14px">Basics: logit and likelihood</h2>\n<p class="lede">The two workhorses of the field, built from school mathematics: how a score becomes a probability, and how to decide whether a more complicated model is worth it.</p>\n'
NEW += tool("odds", 14, "Probability, odds, log-odds", "Three ways to write the same chance", "Odds are the probability divided by its complement. Log-odds are the logarithm of the odds, and they are the scale a logit model works on: the score. A coefficient adds to the log-odds, which multiplies the odds by e to the power of the coefficient.", TOOLS["odds"])
NEW += tool("lrbasic", 15, "Likelihood ratio test", "Does a seat belt matter?", "The restricted model gives both groups one injury share; the unrestricted model gives each its own. The statistic is −2 × [LL(restricted) − LL(unrestricted)], compared with a chi-square critical value. Move the injury counts and watch the verdict change.", TOOLS["lrc"], "“Not rejected” does not prove the simpler model is true; the data just cannot tell the two apart.")
NEW += '<h2 id="restricted" style="margin-top:14px">Restricted and unrestricted models, animated</h2>\n<p class="lede">The unrestricted model is free to choose every parameter. The restricted model is the same model with some parameters locked: set to zero, set equal to each other, or fixed at borrowed values. The test asks whether the locks cost more fit than chance alone would explain.</p>\n'
NEW += tool("oneortwo", 16, "Animation", "One line or two?", "Two groups of crashes and one question: is the injury share the same in both? Press Next step and watch a model with one number and a model with two numbers fit the same two bars.", TOOLS["fit"])
NEW += tool("locks", 17, "Animation", "Restrictions are locks", "Every restricted model is the unrestricted model with locks on some parameters. The degrees of freedom of the test are the number of locks. Choose an example.", TOOLS["locks"].replace('class="go ghost"', 'class="go" style="background:transparent;color:var(--accent)"'))
NEW += tool("chance", 18, "Animation", "What does chance alone look like?", "Even when a restriction is exactly true, the free model fits a little better by luck. This tool invents studies in which the seat belt truly makes no difference and piles up their statistics. The pile is the chi-square distribution; the share of it beyond your statistic is the p-value.", TOOLS["sim"].replace('class="go ghost"', 'class="go" style="background:transparent;color:var(--accent)"'))
NEW += tool("ruler", 19, "Animation", "Degrees of freedom move the ruler", "Each lock gives chance one more way to open a gap between the two models, so with more locks the critical value moves to the right.", TOOLS["dfr"])
TH = [("time", "Time: which effects change, and for whom?"), ("groups", "Groups: let the data suggest the split"), ("learning", "Machine learning against statistical models"), ("conflicts", "Conflicts: making near-miss estimates dependable"), ("practice", "Good practice: predicting and reporting effects")]
NEW += '<h2 id="research" style="margin-top:14px">What current research is doing</h2>\n<p class="lede">Eight recent papers from <i>Analytic Methods in Accident Research</i> in plain words. Checked in November 2026; the summaries follow the published abstracts, so read the papers before citing them.</p>\n'
for k, t in TH:
    NEW += f'<section class="tool"><span class="n">Research direction</span>\n<h2>{t}</h2>\n' + "".join(f'<p><b>{r["authors"]} ({r["year"]}).</b> {r["title"]}. <i>AMAR</i>{" " + r["volume"] + "," if r["volume"] else ","} {r["pages"]}.<br>{r["plain"]}' + (f' <a href="https://doi.org/{r["doi"]}" style="color:var(--accent)">Open the paper</a>' if r["doi"] else "") + '</p>' for r in REFS if r.get("theme") == k) + '</section>\n'
NEW += '<section class="tool"><span class="n">Starter questions</span>\n<h2>Six ideas for a first project</h2>\n<p>Suggestions for learning the methods on real data, not findings.</p><p><b>1 · Add a year.</b> Extend a published design by one year: are the “stable” effects still stable?<br><b>2 · Cluster first.</b> Split the same crashes by road class, by clustering and by hidden classes, and compare the fit.<br><b>3 · Machine against model.</b> Do a classifier and a random parameters logit agree on the direction of each effect?<br><b>4 · Transfer across regions.</b> Does a model from one region fit another?<br><b>5 · How fragile is the threshold?</b> Re-estimate conflict-based crash risk for several thresholds and sample sizes.<br><b>6 · Report it twice.</b> Compute marginal effects by two methods and show where they differ.</p></section>\n'
s = BASE
s = s.replace("--amber-soft:#F6DFB8;", "--amber-soft:#F6DFB8; --amber-fill:#E9A63A;").replace("--amber-soft:#4A3A1A;", "--amber-soft:#4A3A1A; --amber-fill:#F2B450;")
assert s.count("--amber-fill") == 3
s = s.replace(".note{font-size:14px;color:var(--muted)}", ".note{font-size:14px;color:var(--muted)}\n.scroll{overflow-x:auto;border-radius:10px} .scroll svg.chart{min-width:620px} .ctl select,.ctl input[type=number]{max-width:100%} button.go:disabled{cursor:default}")
s = s.replace("Five small tools for the ideas behind papers in <i>Analytic Methods in Accident Research</i>.", "Nineteen small tools for the ideas and models behind papers in <i>Analytic Methods in Accident Research</i>: five on the core ideas, two on the multinomial logit, six that follow a full severity study, two on the basics and four animations on restricted and unrestricted models, followed by a plain-language guide to current research.")
s = s.replace('<a href="#quiz">5 Which issue is it?</a></nav>', '<a href="#quiz">5 Which issue is it?</a><a href="#mnl">6 Multinomial logit</a><a href="#likelihood">7 Maximum likelihood</a><a href="#chisquare">8 Chi-square</a><a href="#selection">9 Selection</a><a href="#random">10 Random parameters</a><a href="#marginal">11 Marginal effects</a><a href="#lrtest">12 Likelihood ratio tests</a><a href="#count">13 Counting tests</a><a href="#odds">14 Odds and log-odds</a><a href="#lrbasic">15 Likelihood ratio basics</a><a href="#restricted">16–19 Restricted vs unrestricted</a><a href="#research">Current research</a></nav>')
a = s.index('<p class="note">Companion to the slide deck')
s = s[:a] + NEW + s[a:]
s = s.replace("Companion to the slide deck “AMAR Methods for Beginners”.", "Companion to the lecture “Methods in Accident Research for Beginners”.")
import re
s = re.sub(r'(<svg class="chart".*?</svg>)', lambda m: '<div class="scroll">' + m.group(1) + '</div>', s, flags=re.S)
shim = """var $ = function (id) { return document.getElementById(id); }, css = function (v) { return getComputedStyle(document.documentElement).getPropertyValue(v).trim(); }, f2 = function (v, d) { return (v < 0 ? '−' : '') + Math.abs(v).toFixed(d === undefined ? 2 : d); }, REDUCED = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches, initSteps = function () {};
function txt(x, y, s, o) { o = o || {}; return '<text x="' + x + '" y="' + y + '" font-size="' + (o.size || 15) + '" font-family="Inter,sans-serif" font-weight="' + (o.w || 500) + '" text-anchor="' + (o.a || 'middle') + '" fill="' + (o.c || css('--fg')) + '">' + s + '</text>'; }
function onTheme(fn) { if (window.matchMedia) matchMedia('(prefers-color-scheme: dark)').addEventListener('change', fn); new MutationObserver(fn).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] }); }
"""
s += "\n<script>\n(function () {\n" + shim + (JS / "mnl.js").read_text() + "\n})();\n" + (JS / "study.js").read_text() + (JS / "foundations.js").read_text() + (JS / "restricted.js").read_text() + "</script>\n"
Path("amar-methods-lab.html").write_text(s); print("artifact bytes", len(s))
